27	
28	public class DialogueSystem : ISystem<GameState>
29	{
30	    private readonly World _world;
31	    private readonly Entity _rootEntity;
32	    private readonly DialogueState _dialogueState;
33	    private readonly BitmapFont _font;
34	    private readonly Transform _rootTransform;
35	    private readonly DrawLayerMap _layers;
36	
37	    // Yarn runtime
38	    private readonly Yarn.Dialogue _yarnDialogue;
39	    private readonly DialogueRunner _dialogueRunner;
40	    private readonly InMemoryVariableStorage _variableStorage;
41	
42	    public bool IsEnabled { get; set; } = true;
43	
44	    public DialogueSystem(World world, ContentManager content, GraphicsDevice graphicsDevice, int virtualWidth, int virtualHeight, DrawLayerMap layers, IEnumerable<string> dialogueContentPaths = null)
45	    {
46	        _world = world;
47	        _layers = layers ?? throw new ArgumentNullException(nameof(layers));
48	        world.Subscribe(this);
49	
50	        // Load assets
51	        var dialogBoxTexture = content.Load<Texture2D>("Dialouge UI/dialog box medium");
52	        _font = content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt");
53	        var indicatorSheet = content.Load<Texture2D>("Dialouge UI/dialog box character finished talking click to continue indicator - spritesheet");
54	        var indicatorTexture = indicatorSheet.Crop(new Rectangle(96, 0, 16, 16), graphicsDevice);
55	
56	        // Layout constants (UI coordinates, virtual resolution)
57	        var boxWidth = virtualWidth - 40;
58	        var boxHeight = 120;
59	        var rootPosition = new Vector2(20, virtualHeight - boxHeight - 20);
60	        var textOffset = new Vector2(16, 16);
61	        var indicatorOffset = new Vector2(boxWidth - 28, boxHeight - 24);
62	
63	        // Create root entity
64	        _rootTransform = new Transform(rootPosition);
65	        _rootEntity = world.CreateEntity();
66	        _rootEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueRoot"));
67	        _rootEntity.Set(_rootTransform);
68	        _dialogueState = new DialogueState();
69	        _rootEntity.Set(_dialogueState);
70	
71	        // Create box child entity
72	        _dialogueState.BoxEntity = world.CreateEntity();
73	        _dialogueState.BoxEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueBox"));
74	        _dialogueState.BoxEntity.Set(new Transform());
75	        _dialogueState.BoxEntity.SetParent(_rootEntity);
76	        _dialogueState.BoxEntity.Set(new SpriteInfo
77	        {
78	            SpriteSheet = dialogBoxTexture,
79	            Source = new Rectangle(0, 0, dialogBoxTexture.Width, dialogBoxTexture.Height),
80	            Size = new Vector2(boxWidth, boxHeight),
81	            Color = Color.White,
82	            Target = RenderTargetID.UI,
83	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI),
84	            NinePatchData = new NinePatchInfo(
85	                23,
86	                new Rectangle(0, 0, 23, 23),
87	                new Rectangle(23, 0, 1, 23),
88	                new Rectangle(24, 0, 23, 23),
89	                new Rectangle(0, 23, 23, 1),
90	                new Rectangle(23, 23, 1, 1),
91	                new Rectangle(24, 23, 23, 1),
92	                new Rectangle(0, 24, 23, 23),
93	                new Rectangle(23, 24, 1, 23),
94	                new Rectangle(24, 24, 23, 23))
95	        });
96	        _dialogueState.BoxEntity.Set(new DrawComponent
97	        {
98	            Type = DrawElementType.Sprite,
99	            Target = RenderTargetID.UI
100	        });
101	
102	        // Create text child entity
103	        _dialogueState.TextEntity = world.CreateEntity();
104	        _dialogueState.TextEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueText"));
105	        _dialogueState.TextEntity.Set(new Transform(textOffset));
106	        _dialogueState.TextEntity.SetParent(_rootEntity);
107	        _dialogueState.TextEntity.Set(new DynamicText
108	        {
109	            Target = RenderTargetID.UI,
110	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
111	            Font = _font,
112	            Color = Color.SaddleBrown,
113	            Scale = 0.5f,
114	            RevealingSpeed = 20,
115	            RevealStartTime = float.NaN,
116	            IsRevealed = false,
117	            VisibleCharacterCount = 0,
118	            TextContent = ""
119	        });
120	        _dialogueState.TextEntity.Set(new DrawComponent
121	        {
122	            Type = DrawElementType.Text,
123	            Target = RenderTargetID.UI
124	        });
125	
126	        // Create indicator child entity
127	        _dialogueState.IndicatorEntity = world.CreateEntity();
128	        _dialogueState.IndicatorEntity.Set(new EntityInfo(nameof(EntityType.Interface), "DialogueIndicator"));
129	        _dialogueState.IndicatorEntity.Set(new Transform(indicatorOffset));
130	        _dialogueState.IndicatorEntity.SetParent(_rootEntity);
131	        _dialogueState.IndicatorEntity.Set(new SpriteInfo
132	        {
133	            SpriteSheet = indicatorTexture,
134	            Source = new Rectangle(0, 0, indicatorTexture.Width, indicatorTexture.Height),
135	            Size = new Vector2(16, 16),
136	            Color = Color.White,
137	            Target = RenderTargetID.UI,
138	            LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f)
139	        });
140	        _dialogueState.IndicatorEntity.Set(new DrawComponent
141	        {
142	            Type = DrawElementType.Sprite,
143	            Target = RenderTargetID.UI
144	        });
145	
146	        // Set up Yarn runtime
147	        var paths = dialogueContentPaths ?? new[] { "Dialogues/hello_world" };
148	        _dialogueRunner = new DialogueRunner();
149	        _variableStorage = new InMemoryVariableStorage();
150	        _yarnDialogue = new Yarn.Dialogue(_variableStorage)
151	        {
152	            LogDebugMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn] {msg}"),
153	            LogErrorMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn ERROR] {msg}"),
154	            LineHandler = OnYarnLine,
155	            OptionsHandler = OnYarnOptions,
156	            CommandHandler = OnYarnCommand,
157	            NodeStartHandler = OnYarnNodeStart,
158	            NodeCompleteHandler = OnYarnNodeComplete,
159	            DialogueCompleteHandler = OnYarnDialogueComplete,
160	        };
161	
162	        // Load all yarn programs and combine via protobuf merge
163	        Yarn.Program combinedProgram = null;
164	        foreach (var path in paths)
165	        {
166	            var yarnProgram = content.Load<YarnProgram>(path);
167	            _dialogueRunner.AddStringTable(yarnProgram);
168	            var program = yarnProgram.GetProgram();
169	            if (combinedProgram == null)
170	            {
171	                combinedProgram = program;
172	            }
173	            else
174	            {
175	                combinedProgram.MergeFrom(program);
176	            }
177	        }
178	        _yarnDialogue.SetProgram(combinedProgram);
179	    }
180	
181	    // --- Yarn callbacks (fire synchronously during Continue()) ---
182	
183	    private void OnYarnLine(Line line)
184	    {
185	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
186	
187	        // Parse "Speaker: text" format
188	        string? speaker = null;
189	        var displayText = text;
190	        var colonIndex = text.IndexOf(':');
191	        if (colonIndex > 0 && colonIndex < 30)
192	        {
193	            speaker = text[..colonIndex].Trim();
194	            displayText = text[(colonIndex + 1)..].Trim();
195	        }
196	
197	        _dialogueState.CurrentPhase = DialoguePhase.Line;
198	        _dialogueState.CurrentSpeaker = speaker;
199	        _dialogueState.WaitingForInput = false;
200	
201	        // Set text content and reset reveal animation
202	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
203	        dynamicText.TextContent = displayText;
204	        dynamicText.VisibleCharacterCount = 0;
205	        dynamicText.IsRevealed = false;
206	        dynamicText.RevealStartTime = float.NaN;
207	
208	        HideIndicator();
209	        HideOptions();
210	    }
211	
212	    private void OnYarnOptions(OptionSet optionSet)
213	    {
214	        _dialogueState.CurrentPhase = DialoguePhase.Options;
215	        _dialogueState.CurrentOptions.Clear();
216	        _dialogueState.CurrentOptionIDs.Clear();
217	        _dialogueState.SelectedOptionIndex = 0;
218	        _dialogueState.WaitingForInput = true;
219	
220	        foreach (var option in optionSet.Options)
221	        {
222	            if (!option.IsAvailable) continue;
223	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
224	            _dialogueState.CurrentOptions.Add(text);
225	            _dialogueState.CurrentOptionIDs.Add(option.ID);
226	        }
227	
228	        // Clear the main text line
229	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
230	        dynamicText.TextContent = "";
231	        dynamicText.VisibleCharacterCount = 0;
232	
233	        ShowOptions();
234	        HideIndicator();
235	    }
236	
237	    private void OnYarnCommand(Command command)
238	    {
239	        global::System.Diagnostics.Debug.WriteLine($"[Yarn Command] {command.Text}");
240	    }
241	
242	    private void OnYarnNodeStart(string nodeName)
243	    {
244	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node started: {nodeName}");
245	    }
246	
247	    private void OnYarnNodeComplete(string nodeName)
248	    {
249	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node complete: {nodeName}");
250	    }
251	
252	    private void OnYarnDialogueComplete()
253	    {
254	        _dialogueState.CurrentPhase = DialoguePhase.Complete;
255	        DeactivateDialogue();
256	    }
257	
258	    // --- Dialogue start trigger (from NPCInteractionSystem) ---
259	
260	    [Subscribe]
261	    private void OnDialogueStart(in DialogueStartMessage message)
262	    {
263	        if (_dialogueState.IsActive) return;
264	        StartYarnDialogue(message.StartNode);
265	    }
266	
267	    // --- Collision trigger ---
268	
269	    [Subscribe]
270	    private void OnCollision(in CollisionMessage message)
271	    {
272	        if (message.Type != CollisionType.Dialogue) return;
273	        if (_dialogueState.IsActive || _dialogueState.WasTriggered) return;
274	
275	        var zoneEntity = message.CollidingEntity;
276	        var nodeName = "HelloWorld";
277	
278	        if (zoneEntity.Has<DialogueZoneComponent>())
279	        {
280	            var zone = zoneEntity.Get<DialogueZoneComponent>();
281	            if (zone.OneTimeOnly && zone.HasBeenTriggered) return;
282	            nodeName = zone.YarnNodeName;
283	            zone.HasBeenTriggered = true;
284	        }
285	
286	        StartYarnDialogue(nodeName);
287	    }
288	
289	    public void StartYarnDialogue(string nodeName)
290	    {
291	        _dialogueState.IsActive = true;
292	        _dialogueState.WasTriggered = true;
293	        _dialogueState.InputConsumed = true; // Prevent immediate advance
294	
295	        // Show dialogue box
296	        _dialogueState.BoxEntity.Set<Visible>();
297	
298	        _world.Publish(new DialogueActiveMessage(true));
299	
300	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
301	        _yarnDialogue.SetNode(nodeName);
302	        _yarnDialogue.Continue();
303	    }
304	
305	    // --- Update loop ---
306	
307	    public void Update(GameState state)
308	    {
309	        if (!_dialogueState.IsActive) return;
310	
311	        // Edge-trigger: release the consumed flag when interact is no longer held
312	        if (!InputState.Interact.Pressed(state))
313	            _dialogueState.InputConsumed = false;
314	
315	        switch (_dialogueState.CurrentPhase)
316	        {
317	            case DialoguePhase.Line:
318	                UpdateLinePhase(state);
319	                break;
320	            case DialoguePhase.Options:
321	                UpdateOptionsPhase(state);
322	                break;
323	        }
324	    }
325	
326	    private void UpdateLinePhase(GameState state)
327	    {
328	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
329	
330	        if (dynamicText.IsRevealed)
331	        {
332	            if (!_dialogueState.IndicatorEntity.Has<Visible>())
333	                _dialogueState.IndicatorEntity.Set<Visible>();
334	            _dialogueState.WaitingForInput = true;
335	        }
336	        else
337	        {
338	            HideIndicator();
339	        }
340	
341	        if (InputState.Interact.Pressed(state) && !_dialogueState.InputConsumed)
342	        {
343	            _dialogueState.InputConsumed = true;
344	
345	            if (!dynamicText.IsRevealed)
346	            {
347	                // Skip reveal — show all text immediately
348	                dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
349	                dynamicText.IsRevealed = true;
350	            }
351	            else
352	            {
353	                // Advance to next yarn content
354	                _yarnDialogue.Continue();
355	            }
356	        }
357	    }
358	
359	    private void UpdateOptionsPhase(GameState state)
360	    {
361	        if (InputState.Up.Pressed(state) && !_dialogueState.InputConsumed)
362	        {
363	            _dialogueState.InputConsumed = true;
364	            _dialogueState.SelectedOptionIndex =
365	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
366	            UpdateOptionHighlights();
367	        }
368	        else if (InputState.Down.Pressed(state) && !_dialogueState.InputConsumed)
369	        {
370	            _dialogueState.InputConsumed = true;
371	            _dialogueState.SelectedOptionIndex =
372	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
373	            UpdateOptionHighlights();
374	        }
375	
376	        // Release consumed flag when no navigation or interact keys are held
377	        if (!InputState.Up.Pressed(state) && !InputState.Down.Pressed(state) && !InputState.Interact.Pressed(state))
378	            _dialogueState.InputConsumed = false;
379	
380	        if (InputState.Interact.Pressed(state) && !_dialogueState.InputConsumed)
381	        {
382	            _dialogueState.InputConsumed = true;
383	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
384	            HideOptions();
385	            _yarnDialogue.SetSelectedOption(yarnOptionID);
386	            _yarnDialogue.Continue();
387	        }
388	    }
389	
390	    // --- Option entity management ---
391	
392	    private void ShowOptions()
393	    {
394	        HideOptions();
395	
396	        const float startY = 16f;
397	        const float optionSpacing = 24f;
398	
399	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
400	        {
401	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
402	            var fullText = prefix + _dialogueState.CurrentOptions[i];
403	
404	            var optionEntity = _world.CreateEntity();
405	            optionEntity.Set(new EntityInfo(nameof(EntityType.Interface), $"DialogueOption{i}"));
406	            optionEntity.Set(new Transform(new Vector2(16, startY + i * optionSpacing)));
407	            optionEntity.SetParent(_rootEntity);
408	            optionEntity.Set(new DynamicText
409	            {
410	                Target = RenderTargetID.UI,
411	                LayerDepth = _layers.GetDepth(GameDrawLayer.DialogueUI, +0.01f),
412	                Font = _font,
413	                Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown,
414	                Scale = 0.5f,
415	                RevealingSpeed = 0, // Instant reveal
416	                RevealStartTime = 0,
417	                IsRevealed = true,
418	                VisibleCharacterCount = fullText.Length,
419	                TextContent = fullText
420	            });
421	            optionEntity.Set(new DrawComponent
422	            {
423	                Type = DrawElementType.Text,
424	                Target = RenderTargetID.UI
425	            });
426	            optionEntity.Set<Visible>();
427	
428	            _dialogueState.OptionEntities.Add(optionEntity);
429	        }
430	    }
431	
432	    private void UpdateOptionHighlights()
433	    {
434	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
435	        {
436	            var entity = _dialogueState.OptionEntities[i];
437	            if (!entity.IsAlive) continue;
438	
439	            ref var dt = ref entity.Get<DynamicText>();
440	            var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
441	            dt.TextContent = prefix + _dialogueState.CurrentOptions[i];
442	            dt.VisibleCharacterCount = dt.TextContent.Length;
443	            dt.Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown;
444	        }
445	    }
446	
447	    private void HideOptions()
448	    {
449	        foreach (var entity in _dialogueState.OptionEntities)
450	        {
451	            if (entity.IsAlive) entity.Dispose();
452	        }
453	        _dialogueState.OptionEntities.Clear();
454	    }
455	
456	    private void HideIndicator()
457	    {
458	        if (_dialogueState.IndicatorEntity.Has<Visible>())
459	            _dialogueState.IndicatorEntity.Remove<Visible>();
460	    }
461	
462	    // --- Deactivation ---
463	
464	    private void DeactivateDialogue()
465	    {
466	        _dialogueState.IsActive = false;
467	        _dialogueState.WasTriggered = false;
468	        _dialogueState.CurrentPhase = DialoguePhase.None;
469	        _dialogueState.WaitingForInput = false;
470	        _dialogueState.CurrentSpeaker = null;
471	
472	        HideOptions();
473	
474	        // Hide box
475	        if (_dialogueState.BoxEntity.Has<Visible>())
476	            _dialogueState.BoxEntity.Remove<Visible>();
477	
478	        var boxDraw = _dialogueState.BoxEntity.Get<DrawComponent>();
479	        boxDraw.Texture = null;
480	
481	        // Clear text
482	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicText>();
483	        dynamicText.VisibleCharacterCount = 0;
484	        dynamicText.IsRevealed = false;
485	        dynamicText.TextContent = "";
486	
487	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
488	        textDraw.Text = null;
489	        textDraw.Font = null;
490	
491	        // Hide indicator
492	        HideIndicator();
493	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
494	        indicatorDraw.Texture = null;
495	
496	        _world.Publish(new DialogueActiveMessage(false));
497	    }
498	
499	    public void Dispose()
500	    {
501	        GC.SuppressFinalize(this);
502	    }
503	}
